insert into public.qcm_bank
  (bank_id, otr_number, module, chapter, context, star, corrected, stem, options, justification, sources)
values
(601, 34, 'Rhumatologie', 'Sciatique et rachis médical', NULL, false, true, 'Les affirmations suivantes sont correctes SAUF UNE Laquelle ?', '[{"l":"A","t":"Au niveau lombaire, les racines nerveuses prennent la numérotation de la vertèbre sous-jacente à leur orifice de sortie","c":true},{"l":"B","t":"La compression radiculaire ne suffit pas pour expliquer la douleur radiculaire","c":false},{"l":"C","t":"L’aréflexie achilléenne témoigne d’une atteinte de S1","c":false},{"l":"D","t":"Une infiltration de corticoïdes en épidural est un traitement admis dans une sciatique causée par une hernie discale","c":false},{"l":"E","t":"Une cruralgie peut se manifester par un dérobement du genou","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(602, 34, 'Rhumatologie', 'Sciatique et rachis médical', NULL, false, true, 'Quelle(s) mesure(s) proposeriez-vous à un patient manutentionnaire dont la sciatique commune a régressé sous traitement médical ?', '[{"l":"A","t":"Nucléolyse chimique","c":false},{"l":"B","t":"Rééducation appropriée du rachis lombaire","c":true},{"l":"C","t":"Cure chirurgicale de hernie discal","c":false},{"l":"D","t":"Reclassement professionnel.","c":true},{"l":"E","t":"Les 4 propositions sont justes:","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(603, 39, 'Rhumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', NULL, false, true, 'Devant les éléments suivants. Indiquez celui ou ceux qui sont évocateurs d’une sciatique de topographie L5:', '[{"l":"A","t":"Douleur de la face postéro-externe de la cuisse postérieure de la jambe en arrière de la malléole externe","c":false},{"l":"B","t":"Hypoesthésie du dos du pied","c":true},{"l":"C","t":"Abolition du réflexe rotulien","c":false},{"l":"D","t":"Marche sur les talons impossible","c":true},{"l":"E","t":"Diminution de la force de l’extenseur propre du gros orteil","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(604, 34, 'Rhumatologie', 'Sciatique et rachis médical', NULL, false, true, 'Quel(s) signe(s) est(sont) inhabituel(s) dans une sciatique L5 ?', '[{"l":"A","t":"Abolition du réflexe achilléen","c":true},{"l":"B","t":"Abolition du réflexe rotulien","c":true},{"l":"C","t":"Paresthésies du dos du pied","c":false},{"l":"D","t":"Diminution de force de la dorsiflexion du gros orteil","c":true},{"l":"E","t":"Hypoesthésie de la plante du pied","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(605, 34, 'Rhumatologie', 'Sciatique et rachis médical', NULL, false, true, 'On peut traiter par chimionucléolyse', '[{"l":"A","t":"Les sciatiques par sténose lombaire latérale","c":false},{"l":"B","t":"Les sciatiques par spondylolisthésis","c":false},{"l":"C","t":"Les lombalgies récidivantes","c":false},{"l":"D","t":"Certaines sciatiques par hernie discale","c":true},{"l":"E","t":"Les sciatiques par hernie discale persistant après une chimionucléolyse","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(606, 34, 'Rhumatologie', 'Sciatique et rachis médical', NULL, false, true, 'Une radiographie standard du rachis lombaire nous montre un pincement L4-L5 avec un flou des plateaux vertébraux de part et d’autre. Cet aspect correspond à:', '[{"l":"A","t":"une fracture des deux vertèbres l4 et l5,","c":false},{"l":"B","t":"une compression radiculaire par hernie discale,","c":false},{"l":"C","t":"une spondylite de l5,","c":false},{"l":"D","t":"une spondylodiscite l4-l5,","c":true},{"l":"E","t":"une spondylite de Romanus.","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(607, 34, 'Rhumatologie', 'Lombalgies et lombosciatalgies', NULL, false, true, 'Une sciatique par hernie discale est occasionnée par (cochez les réponses justes)', '[{"l":"A","t":"Une détérioration discale avec migration de l ’anneau fibreux à la partie antéro-latérale du disque.","c":false},{"l":"B","t":"Une hernie postérieure ou postéro- latérale du nucleus pulposus","c":true},{"l":"C","t":"Par débord ou protrusion discale","c":false},{"l":"D","t":"Par un conflit disco-radiculaire","c":true},{"l":"E","t":"Un spondylolysthesis","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(608, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', NULL, false, true, 'Une sciatique peut être en rapport avec:', '[{"l":"A","t":"Hernie discale L4 L5 ou L5 S1","c":false},{"l":"B","t":"Un mal de Pott L5 S1","c":false},{"l":"C","t":"Une spondylodyscite inflammatoire des spondyloarthrites","c":false},{"l":"D","t":"Un myélome multiple","c":false},{"l":"E","t":"Toutes ces réponses sont justes","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(609, 34, 'Rhumatologie', 'Sciatique et rachis médical', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Au cours d’une lombo-sciatique commune la radiographie standard du rachis lombaire peut être:', '[{"l":"A","t":"Normale","c":true},{"l":"B","t":"Montre un pincement discale L5-S1","c":true},{"l":"C","t":"Montre un baillement de l’espace inter somatique L4-L5","c":true},{"l":"D","t":"Une fracture de la LA","c":false},{"l":"E","t":"Un pincement discal avec irregularité des plateaux vertébraux L4-L5","c":false}]'::jsonb, NULL, '["EMD OTR section A"]'::jsonb),
(610, 34, 'Rhumatologie', 'Sciatique et rachis médical', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Une sciatique commune par hemie discale se manifeste par:', '[{"l":"A","t":"Début brutal après effort","c":false},{"l":"B","t":"Douleur irradiant au creux inguinal","c":false},{"l":"C","t":"Douleur de type mécanique","c":false},{"l":"D","t":"Impulsivité aux étemuements","c":false},{"l":"E","t":"Dérouillage matinal supérieur à une heure","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(611, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Une lombosciatique symptomatique peut être secondaire à', '[{"l":"A","t":"Epidurite métastatique","c":false},{"l":"B","t":"Protrusion dacale","c":false},{"l":"C","t":"Spondylodiscite tuberculeuse","c":false},{"l":"D","t":"Polyartvite rhumar rhumatoide","c":false},{"l":"E","t":"Osteome asticide","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(612, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Les déformations des mains et poignets au cours de la polyarthrite rhumatoïde sont: cocher la ou les réponse(s) Juste(s):', '[{"l":"A","t":"La touche de piano","c":true},{"l":"B","t":"La déviation cubitale des doigts.","c":true},{"l":"C","t":"Main de Jaccoud","c":false},{"l":"D","t":"Le dos de chameau.","c":true},{"l":"E","t":"Toutes les réponses sont justes,","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(613, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Les déformations caractéristiques de la polyarthrite rhumatoïde à la phase d’état sont: cocher la ou les réponse(s) justes(s):', '[{"l":"A","t":"La déformation en col de cygne.","c":true},{"l":"B","t":"Le pouce en z","c":true},{"l":"C","t":"La déviation de la troisième phalange avec nodosités d’Heberden.","c":false},{"l":"D","t":"La déformation des doigts en maillet.","c":true},{"l":"E","t":"les durillons plantaires","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(614, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Le bilan biologique de la polyarthrite rhumatoïde peut retrouver: cocher la ou les réponse(s) juste(s)', '[{"l":"A","t":"Une CRP positive","c":false},{"l":"B","t":"Des anticorps antifilagrine positifs","c":false},{"l":"C","t":"Une anémie hypochrome microcytaire","c":false},{"l":"D","t":"Une réaction de Waaler Rose 2 1/64","c":false},{"l":"E","t":"Toutes les réponses sont justes","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(615, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, true, true, 'Les déformations caractéristiques de la polyarthrite rhumatoïde à la phase d’état sont: LA OU LES RF', '[{"l":"A","t":"La déformation en col de cygne.","c":false},{"l":"B","t":"Le pouce en Z.","c":false},{"l":"C","t":"La déviation de la troisième phalange avec nodosités d’Heberden.","c":true},{"l":"D","t":"La déformation des doigts en maillet.","c":false},{"l":"E","t":"Les durillons plantaires.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(616, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'La polyarthrite rhumatoïde: la ou les RJ(s):', '[{"l":"A","t":"Touche souvent l’homme jeune.","c":false},{"l":"B","t":"Un début juvénile de la maladie est très fréquent","c":false},{"l":"C","t":"Peut avoir une évolution par poussée-rémission.","c":true},{"l":"D","t":"S’accompagne toujours d’une sérologie rhumatoïde positive.","c":false},{"l":"E","t":"Epargne les sacro-iliaques et les interphalangiennes distales","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(617, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'La polyarthrite rhumatoïde est: la ou les RF(s):', '[{"l":"A","t":"Plus fréquente chez l’homme jeune","c":true},{"l":"B","t":"D’étiopathogénie infectieuse","c":true},{"l":"C","t":"Responsable ??? Radiographique","c":false},{"l":"D","t":"Accompagne souvent d’une ??? Inflammatoire","c":true},{"l":"E","t":"A l’origine d’arthrite périphérique déformante","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(618, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Les atteintes extra-articulaires suivantes peuvent être constatées au cours de la polyarthrites rhumatoïde sauf une, laquelle ?', '[{"l":"A","t":"Nodules sous-cutanées","c":false},{"l":"B","t":"Syndrome sec","c":false},{"l":"C","t":"Uvéite antérieure aigue","c":true},{"l":"D","t":"Péricardite","c":false},{"l":"E","t":"Pleurésie séro-fibrineuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(619, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Concernant la polyarthrite rhumatoïde, quelle est l’association juste? 1/ La polyarthrite rhumatoïde est un rhumatisme dégénératif chronique 2/ Une mono arthrite chronique est le mode de début le plus fréquent 3/ Le bilan immunologique (FR/ACPA) peut être négatif à la phase de début 4/Le bilan inflammatoire est souvent positif au cours d’une poussée inflammatoire 5/ La déformation en boutonnière correspond à une flexion de l’IPP et une hyper extension de l’IPD', '[{"l":"A","t":"1+2+3 B. 2+3+4 C. 1+3+5","c":false},{"l":"D","t":"3+4+5 E. 1+2+5","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(620, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, true, true, 'Concernant la polyarthrite rhumatoïde (PR); choisissez-la ou les réponses fausses', '[{"l":"A","t":"La PR ne s’observe jamais chez le sujet âgé","c":true},{"l":"B","t":"La PR est un rhumatisme inflammatoire chronique å potentiel destructeur","c":false},{"l":"C","t":"Les anticorps anti-nucléaires en Sont les principaux marqueurs immunologiques","c":true},{"l":"D","t":"Les radiographies standard peuvent être normales au début de la maladie","c":false},{"l":"E","t":"Les signes extra-articulaires sont un mode de début très fréquent de la PR","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(621, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Concernant le syndrome de Sjörgen, les RJs:', '[{"l":"A","t":"Une polyarthrite déformante et destructrice est évocatrice.","c":false},{"l":"B","t":"Un syndrome sec inexpliqué par une autre étiologie","c":true},{"l":"C","t":"Un bilan immunologique positif avec présence d’Ac anti SSA et/ou SSB","c":true},{"l":"D","t":"Une biopsie des grandes salivaires est indispensable pour confirmer le diagnostic","c":true},{"l":"E","t":"La sécheresse est exclusivement oculaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(622, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Le bilan ??? Immunité au cours des maladies de système:', '[{"l":"A","t":"Les FAN peuvent être positifs dans (toutes ?) Les maladies de système","c":true},{"l":"B","t":"Les FR sont positifs uniquement dans la polyarthrite rhumatoïde","c":false},{"l":"C","t":"les anticorps anti ?????","c":false},{"l":"D","t":"La CRP fait partie du bilan d’auto–immunité","c":false},{"l":"E","t":"Les FAN sont spécifiques de la maladie lupique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(623, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Concernant la maladie lupique, quels sont les auto-anticorps les plus caractéristiques:', '[{"l":"A","t":"Le facteur rhumatoïde","c":false},{"l":"B","t":"Un anticorps anti-Sm","c":true},{"l":"C","t":"Les anticorps anti SSA/SSb","c":false},{"l":"D","t":"Les ACPA","c":false},{"l":"E","t":"Les anticorps anti phospholipides","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(624, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Les facteurs de risques de survenue d’ostéoporose: Cocher la ou les Réponse(s) juste(s)', '[{"l":"A","t":"Contraceptifs oraux","c":false},{"l":"B","t":"Traitement au long cours par les corticoïdes","c":true},{"l":"C","t":"La polyarthrite rhumatoïde","c":true},{"l":"D","t":"Ménopause survenue à 50 ans","c":false},{"l":"E","t":"Traitement prolongé par l’héparine","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(625, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'On retient en faveur d’une spondylarthrite ankylosante (Cocher la ou les Réponses justes)', '[{"l":"A","t":"Oligoarthrite asymétriques des membres inférieurs","c":true},{"l":"B","t":"Une polyarthrite distale, symétrique et destructrice","c":false},{"l":"C","t":"Talalgies","c":true},{"l":"D","t":"Aspect d’orteil en saucisse","c":true},{"l":"E","t":"Syndrome de Raynaud","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(626, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Quels sont les diagnostics différentiels possibles?', '[{"l":"A","t":"Arthrose multifocale","c":false},{"l":"B","t":"Ostéoporose","c":false},{"l":"C","t":"Maladie lupique","c":true},{"l":"D","t":"Polyarthrite rhumatoïde","c":true},{"l":"E","t":"Syndrome ostéomalacique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(627, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Parmi les propositions suivantes, lesquelles sont responsables d’hyperuricémie ?', '[{"l":"A","t":"une insuffisance rénale chronique.","c":true},{"l":"B","t":"une hémopathie surtout les syndromes myéloprolifératifs.","c":true},{"l":"C","t":"Spondylarthrite ankylosante.","c":false},{"l":"D","t":"Un psoriasis étendu.","c":true},{"l":"E","t":"Polyarthrite rhumatoïde,","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(628, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Devant une polyarthrite rhumatoïde en poussée, Il faut', '[{"l":"A","t":"mettre l’articulation au repos","c":true},{"l":"B","t":"associer de la balnéothérapie","c":false},{"l":"C","t":"Porter une orthèse dynamique","c":false},{"l":"D","t":"porter une orthèse en position de fonction","c":true},{"l":"E","t":"un travail musculaire isométrique","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(629, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'On retient en faveur d’une SpA:', '[{"l":"A","t":"Oligoarthrite asymetriques des membres inferieurs","c":true},{"l":"B","t":"Une polyarthrite distale,symetrique et destructrice","c":false},{"l":"C","t":"Talalgies","c":true},{"l":"D","t":"Aspect d’orteil en saucisse","c":true},{"l":"E","t":"Syndrome de raynaud","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(630, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Les facteurs de risques de survenue d’ostéoporose: La/Les RJ', '[{"l":"A","t":"Contraceptifs oraux","c":false},{"l":"B","t":"Traitement au long cours parle s corticoides","c":true},{"l":"C","t":"La polyarthrite rhumatoide","c":true},{"l":"D","t":"Menopause survenue a50ans","c":false},{"l":"E","t":"Traitement prolonge par l’héparine","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(631, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Concernant le syndrome de Sjörgen: Les RJ', '[{"l":"A","t":"Une polyarthrite déformante et destructrice est évocatrice.","c":false},{"l":"B","t":"Un syndromes ec inexplique par une autre etiologie","c":true},{"l":"C","t":"Un bilan immunologique positif avec presence d’ac anti ssa et/ou ssb","c":true},{"l":"D","t":"Une biopsie des grandes salivaires est indispensable pour confirmer le diagnostic","c":true},{"l":"E","t":"La secheresse est exclusivement oculaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(632, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', NULL, false, true, 'Le bilan d’auto immunité au cours des maladies de système:', '[{"l":"A","t":"Les FAN peuvent être positifs dans toutes Les maladiesdesystème","c":true},{"l":"B","t":"Les fr sont positifs uniquement dans la polyarthrite rhumatoïde","c":false},{"l":"C","t":"Les anticorps anti….","c":false},{"l":"D","t":"L acr p fait partie du bilan d’auto–immunité","c":false},{"l":"E","t":"Les fan sont specifiques dela maladie lupique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(633, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La polyarthrite rhumatoïde est: La/Les RJ', '[{"l":"A","t":"Une spondylarthrite","c":false},{"l":"B","t":"Le rhumatisme inflammatoire chronique le plus frequent","c":true},{"l":"C","t":"Une arthropathie microcristalline.","c":false},{"l":"D","t":"Une maladies ystemi que auto-imm une","c":true},{"l":"E","t":"Un rhumatisme degeneratif","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(634, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Les déformations des mains et poignets au cours de la polyarthrite rhumatoïde sont: La/Les RJ', '[{"l":"A","t":"La touche de piano","c":true},{"l":"B","t":"Ladéviationcubitaledesdoigts.","c":true},{"l":"C","t":"Main de jaccoud","c":false},{"l":"D","t":"Le dos de chameau.","c":true},{"l":"E","t":"Toutes les reponses sont justes,","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(635, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Les déformations caractéristiques de la polyarthrite rhumatoïde à la phase d’état sont:', '[{"l":"A","t":"L ade formation en col de cygne.","c":true},{"l":"B","t":"Le pouce enz","c":true},{"l":"C","t":"La déviation de la troisième phalange avec nodositésd’Heberden.","c":false},{"l":"D","t":"L ade formation des doigts en maillet.","c":true},{"l":"E","t":"les durillons plantaires","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(636, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le bilan biologique de la polyarthrite rhumatoïde peut retrouver: La/Les RJ', '[{"l":"A","t":"Une crp positive","c":false},{"l":"B","t":"Des anticorps antifilagrine positifs","c":false},{"l":"C","t":"Une anemie hypochrome microcytaire","c":false},{"l":"D","t":"Une reaction de waaler rose21/64","c":false},{"l":"E","t":"Toutes les reponses sont justes","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(637, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La polyarthrite rhumatoïde: La/Les RJ', '[{"l":"A","t":"Touche souvent l’homme jeune.","c":false},{"l":"B","t":"Un debut juvenile dela maladie est tres frequent","c":false},{"l":"C","t":"Peut avoir une evolution par poussee-r emission.","c":true},{"l":"D","t":"S’accompagne toujours d’unesérologie rhumatoïde positive.","c":false},{"l":"E","t":"Epargne les sac ro-iliaques et les interphalangiennes distales","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(638, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La polyarthrite rhumatoïde est: La/Les RF', '[{"l":"A","t":"Plus frequente chez l’homme jeune","c":true},{"l":"B","t":"D’etiopathogenie infectieuse","c":true},{"l":"C","t":"Responsable…Radiographique","c":false},{"l":"D","t":"Accompagne souvent d’une…Inflammatoire","c":true},{"l":"E","t":"Al’origine d’arthrite peripherique deformante","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(639, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Au cours de la polyarthrite rhumatoïde débutante: Les RJ', '[{"l":"A","t":"Une polyarthrite distale bilatérale et symétrique est le mode de debut le plus frequent","c":false},{"l":"B","t":"Les douleurs articulaires ne sont pas calme es parle repos","c":true},{"l":"C","t":"Des signes extra-articulaires accompagne nt rarement les arthrites","c":true},{"l":"D","t":"L’échographie articulaire est utile pour d ete cter des synovite s cliniques","c":false},{"l":"E","t":"Une biopsie synoviale est indiquee en cas d’atteinte mono-articulaire","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(640, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Concernant la polyarthrite rhumatoïde: La/Les RF', '[{"l":"A","t":"LaPRnes’observejamaischezlesujetâgé","c":true},{"l":"B","t":"La PR est un rhumatisme inflammatoire chronique å potentiel destructeur","c":false},{"l":"C","t":"Les anticorps anti-nucléairesenSontlesprincipaux marqueurs immunologiques","c":true},{"l":"D","t":"Les radiographies standard peuvent être normales au debut dela maladie","c":false},{"l":"E","t":"Les signes extra-articulaires sont un mode de debut tres frequent delapr","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(641, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi les signes radiographiques suivants, indiquez celui ou ceux que l’on rencontre dans la polyarthrite rhumatoïde:', '[{"l":"A","t":"Erosion des extrémités osseuses articulaires","c":true},{"l":"B","t":"Epaississement des corticales","c":false},{"l":"C","t":"Géodes sous-chondrales","c":true},{"l":"D","t":"Pincement global de l’interligne","c":true},{"l":"E","t":"Déminéralisation en bande des mains","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(642, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Au cours de la polyarthrite rhumatoïde, le facteur rhumatoïde peut être mis en évidence par la réaction de Waaler-Rose et le test du latex:', '[{"l":"A","t":"Chez tous les malades après 3 ans d’évolution","c":false},{"l":"B","t":"Chez 25 % des malades au bout d’un an","c":false},{"l":"C","t":"Chez 75 % des malades au bout d’un an","c":true},{"l":"D","t":"Chez tous les sujets HLA B 27 +","c":false},{"l":"E","t":"Dans les formes graves de la maladie seulement","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(643, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Au point de vue immunologique, les facteurs rhumatoïdes responsables des réactions de Waaler-Rose et du latex sont:', '[{"l":"A","t":"Des IgA anti IgM","c":false},{"l":"B","t":"Des IgG anti IgA","c":false},{"l":"C","t":"Des IgM anti IgG","c":true},{"l":"D","t":"Des IgA anti IgG","c":false},{"l":"E","t":"Des IgM anti IgA","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(644, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'la polyarthrite rhumatoïde est une affection: (cochez la ou les réponses justes)', '[{"l":"A","t":"bénigne et peu invalidante","c":false},{"l":"B","t":"b - généralement mortelle, par la survenue tardive mais constante de manifestations viscérales","c":false},{"l":"C","t":"c - parfois mortelle du fait d’une atteinte cardiaque","c":true},{"l":"D","t":"d - conduisant généralement à une infirmité importante","c":true},{"l":"E","t":"e - pouvant se compliquer d’amylose","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(645, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La polyarthrite rhumatoïde peut être responsable: (cochez la ou les réponses justes)', '[{"l":"A","t":"d’épanchements synoviaux multiples","c":true},{"l":"B","t":"b – d’une sacro-iléite bilatérale","c":false},{"l":"C","t":"c - d’une compression médullaire","c":true},{"l":"D","t":"d - d’un syndrome de raynaud","c":true},{"l":"E","t":"e - d’une vascularite","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(646, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi les propositions suivantes concernant la réaction de Waaler-Rose, laquelle ou lesquelles sont exactes ? (Cochez la ou les réponses justes)', '[{"l":"A","t":"Elle est moins sensible que le test au Latex","c":true},{"l":"B","t":"Elle est plus spécifique que le test au Latex","c":true},{"l":"C","t":"Elle se positive en règle dans les 2 premiers mois d’évolutionde la polyarthrite rhumatoïde","c":false},{"l":"D","t":"Sa négativité après 6 mois d’évolution ne doit pas faireexclure le diagnostic de polyarthrite rhumatoïde","c":true},{"l":"E","t":"Peut être positive au cours du Syndrome de Gougerot Sjögren","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(647, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi les caractères suivants d’un liquide de ponction articulaire quel est celui qui ne se rencontre pas dans la PR ?', '[{"l":"A","t":"Inflammatoire","c":false},{"l":"B","t":"Latex et waaler rose positive","c":false},{"l":"C","t":"Couleur jaune citrin","c":false},{"l":"D","t":"Liquide fluide","c":false},{"l":"E","t":"Présence de microcristaux","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(648, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La polyarthrite rhumatoïde est un rhumatisme inflammatoire chronique caractérisé par:(cochez la réponse juste)', '[{"l":"A","t":"La présence du terrain de prédisposition génétique HLA B27","c":false},{"l":"B","t":"L’atteinte prédominante des grosses articulations et du rachis dorsolombaire.","c":false},{"l":"C","t":"La nette tendance à la symétrie et l’atteinte acromélique.","c":true},{"l":"D","t":"La présence du facteur rhumatoïde dès le début de la maladie","c":false},{"l":"E","t":"La présence d’érosions sur la radiographie standard dès la phase de début.","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(649, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi les modes de début suivants, quel est celui qui est évocateur en priorité d’une polyarthrite rhumatoïde (PR): cochez la bonne réponse.', '[{"l":"A","t":"Début par une atteinte du rachis lombaire.","c":false},{"l":"B","t":"Début par une mono-arthrite aigue dans un contexte fébrile.","c":false},{"l":"C","t":"Début par une atteinte distale bilatérale et symétrique.","c":true},{"l":"D","t":"Début par une oligo-arthrite asymétrique associée à des talalgies.","c":false},{"l":"E","t":"Début par une bi-arthrite des genoux précédée par un épisode de diarrhée.","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(650, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Concernant la polyarthrite rhumatoïde, cochez les réponses justes:', '[{"l":"A","t":"La PR est le rhumatisme inflammatoire le plus fréquent dans le monde","c":true},{"l":"B","t":"Les destructions ostéo-cartilagineuses au cours de la PR sont réversibles spontanément.","c":false},{"l":"C","t":"La polyarthrite bilatérale et symétrique est la forme clinique la plus fréquente au début.","c":false},{"l":"D","t":"Le facteur rhumatoïde et les Ac anti-CCP sont les marqueurs immunologiques les plus importants","c":true},{"l":"E","t":"Un traitement de fond d’emblée est systématiquement indiquée quelque soit la forme clinique.","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(651, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, false, 'On peut observer dans la polyarthrite rhumatoïde une instabilité atloïdo-axoïdienne latente cliniquement en la recherchant systématiquement sur un cliché du cou en flexion antérieure prudent Quelle sera votre prescription parmi les suivantes ?', '[{"l":"A","t":"Repos total au lit, coussin sous la nuque jusqu’à réduction","c":false},{"l":"B","t":"Minerve plâtrée prenant appui sur les épaules et l’occiput","c":false},{"l":"C","t":"Intervention stabilisatrice d’urgence","c":false},{"l":"D","t":"Radiothérapie anti-inflammatoire","c":false},{"l":"E","t":"Collier de Schan","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(652, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Une polyarthrite rhumatoïde débutante peut se manifester par: La/Les RJ', '[{"l":"A","t":"Une uvéite bilatérale","c":false},{"l":"B","t":"Un érythème malaire","c":false},{"l":"C","t":"Un aspect de doigt en fuseau","c":true},{"l":"D","t":"Des douleurs fessières à bascule","c":false},{"l":"E","t":"Un enraidissement matinal","c":true}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(653, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Pour poser le diagnostic de la polyarthrite rhumatoïde, il faut demander: La/Les RF', '[{"l":"A","t":"Une vitesse de sédimentation, un taux de la CRP","c":false},{"l":"B","t":"Un dosage des anticorps anti-CCP","c":false},{"l":"C","t":"Le typage HLA DR4","c":true},{"l":"D","t":"Le facteur rhumatoïde","c":false},{"l":"E","t":"Des radiographies des mains et des pieds","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(654, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Les signes radiologiques suivants sont retrouvés au cours de la polyarthrite rhumatoïde: La/Les RJ', '[{"l":"A","t":"Des érosions osseuses","c":true},{"l":"B","t":"Une déminéralisation épiphysaire en bande","c":true},{"l":"C","t":"Des ostéophytes marginaux","c":false},{"l":"D","t":"Une diminution de la hauteur de l’interligne articulaire","c":true},{"l":"E","t":"Une condensation osseuse sous chondrale","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(655, 31, 'Rhumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', NULL, false, true, 'La luxation postérieure de la hanche avec fracture du cotyle peut être responsable:', '[{"l":"A","t":"D’une paralysie crurale","c":false},{"l":"B","t":"D’une rupture de la vessie","c":false},{"l":"C","t":"D’une lésion de l’artère fémorale","c":false},{"l":"D","t":"D’une nécrose de la tête fémorale","c":true},{"l":"E","t":"D’une coxarthrose","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022","Banque de QCM OTR","Banque de QCM OTR p.19"]'::jsonb),
(656, 31, 'Rhumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', NULL, true, true, 'La(les) complication(s) la(les) plus fréquente(s) à long terme est (sont):', '[{"l":"A","t":"La nécrose de la tête fémorale","c":true},{"l":"B","t":"La suppuration profonde","c":false},{"l":"C","t":"Une ankylose spontanée de la hanche","c":false},{"l":"D","t":"Une fracture du col du fémur","c":false},{"l":"E","t":"Une coxarthrose","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(657, 26, 'Rhumatologie', 'Traumatisme du bassin : fracture, luxation traumatique de la hanche', NULL, false, true, 'La luxation de hanche peut se compliquer de: (Réponses justes) (question annulée)', '[{"l":"A","t":"ostéonécrose de la tête fémorale","c":true},{"l":"B","t":"arthrose coxo-fémorale","c":true},{"l":"C","t":"ossification péri articulaire","c":true},{"l":"D","t":"paralysie du nerf sciatique","c":true},{"l":"E","t":"fracture du cotyle","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(658, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'La fracture uni-tubérositaire externe est: (Cocher la ou les réponses fausses)', '[{"l":"A","t":"La fracture la plus fréquente des plateaux tibiaux","c":false},{"l":"B","t":"S’accompagne toujours d’un enfoncement F","c":true},{"l":"C","t":"Le traitement vise à rétablir les surfaces articulaires","c":false},{"l":"D","t":"Pourvoyeuse d’arthrose du genou","c":false},{"l":"E","t":"C’est une fracture extra articulaire","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(659, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'Une arthrite du genou évoluant depuis 6 mois sans aucune lésion radiologique doit faire évoquer:', '[{"l":"A","t":"une tuberculose","c":true},{"l":"B","t":"une monoarthrite rhumatoïde","c":true},{"l":"C","t":"une poussée congestive d’arthrose","c":false},{"l":"D","t":"une arthropathies tabétique","c":false},{"l":"E","t":"aucune des propositions précédentes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(660, 11, 'Rhumatologie', 'Boiterie chez l’enfant', NULL, false, true, 'Quels sont les éléments cliniques de diagnostic d’une gonarthrose:', '[{"l":"A","t":"Une boiterie d’esquive la marcha","c":true},{"l":"B","t":"Une douleur de type mécanique","c":true},{"l":"C","t":"Présence de signes inflammatoires locaux","c":false},{"l":"D","t":"Réveil avec un dérouillage matinal supérieur 30 min","c":false},{"l":"E","t":"Présence d’un craquement lors de changement on position","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(661, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, 'Quels sont les signes radiologiques d’une arthrose ?', '[{"l":"A","t":"Des microcalcifications intra articulaires","c":true},{"l":"B","t":"Une ostéocondensation de l’os sous chondral","c":false},{"l":"C","t":"Des syndesmophytes à la périphérie de l’articulation","c":true},{"l":"D","t":"Un pincement de l’interligne articulaire,","c":false},{"l":"E","t":"Présence de géodes dans l’os sous chondral","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(662, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'Une ostéotomie tibiale de valgisation peut être réalisée:', '[{"l":"A","t":"Chez un sujet plutôt âgé avec une gonarthrose globale","c":false},{"l":"B","t":"Dans le cas d’échec de prothèse unicompartimentale","c":false},{"l":"C","t":"Pour une gonarthrose interne sur genu varum","c":false},{"l":"D","t":"Pour une gonarthrose externe sur genu valgum","c":true},{"l":"E","t":"Pour une gonarthrose femoropatellaire.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(663, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'Parmi les examens radiologiques suivants, quel est celui qui n’a aucun intérêt pour le diagnostic d’une gonarthrose sur genu varum:', '[{"l":"A","t":"Rx de face en position de schuss","c":false},{"l":"B","t":"Incidence de Maldague","c":true},{"l":"C","t":"Télémétrie des membres inférieurs","c":false},{"l":"D","t":"Radio de face debout en extension","c":false},{"l":"E","t":"Radio de profil debout en extension","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(664, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'Le liquide articulaire dans la gonarthrose a les propriété(s) suivante(s)', '[{"l":"A","t":"Peut être à l’origine d’un choc rotulien","c":true},{"l":"B","t":"Aseptique","c":true},{"l":"C","t":"Un nombre d’éléments blancs inférieur à 2000 éléments/mm3","c":true},{"l":"D","t":"Riche en microcristaux","c":false},{"l":"E","t":"Trouble et fluide","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(665, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'La gonarthrose est un rhumatisme: RJs', '[{"l":"A","t":"Non inflammatoire chronique","c":true},{"l":"B","t":"Unilatéral, unicompartimental","c":false},{"l":"C","t":"Non évolutive","c":false},{"l":"D","t":"Touche surtout l’adulte et le sujet âgé","c":true},{"l":"E","t":"Les facteurs de risque sont: l’obésité et le sexe féminin","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(666, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, 'Les images caractéristiques de la gonarthrose à la radiographie du genou sont:', '[{"l":"A","t":"Un pincement de l’interligne articulaire","c":true},{"l":"B","t":"Des syndesmophytes","c":false},{"l":"C","t":"Ostéocondensation de l’os sous chondral","c":true},{"l":"D","t":"Géodes de l’os sous chondral","c":true},{"l":"E","t":"Déminéralisation osseuse diffuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(667, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'Le liquide articulaire dans la gonarthrose a le(s) propriété(s) suivante(s)', '[{"l":"A","t":"Peut-être à l’origine d’un choc rotulien","c":true},{"l":"B","t":"Aseptique","c":true},{"l":"C","t":"Un nombre d’éléments blancs inférieur à 2000 éléments/mm3","c":true},{"l":"D","t":"Riche en micro cristaux","c":false},{"l":"E","t":"Visqueux, jaunes citrin","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(668, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, true, true, 'La gonarthrose: (la réponse Juste)', '[{"l":"A","t":"Est un rhumatisme inflammatoire chronique,","c":false},{"l":"B","t":"Est la résultante de phénomènes mécaniques seuls.","c":false},{"l":"C","t":"Elle évolue par des poussées congestives et des rémissions.","c":true},{"l":"D","t":"Elle est toujours primitive.","c":false},{"l":"E","t":"Elle est caractérisée par la présence de syndesmophytes à la radiographie.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(669, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'Dans la gonarthrose, on peut utiliser:', '[{"l":"A","t":"des genouillères","c":true},{"l":"B","t":"une canne simple","c":true},{"l":"C","t":"des semelles orthopédiques","c":false},{"l":"D","t":"la balnéothérapie","c":true},{"l":"E","t":"les ultra–sons","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(670, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'La gonarthrose peut être secondaire: choisissez la ou les réponses justes', '[{"l":"A","t":"fracture articulaire du genou","c":true},{"l":"B","t":"chondromatose synoviale","c":true},{"l":"C","t":"mono-arthrite inflammatoire","c":true},{"l":"D","t":"synovite villo-nodulaire","c":false},{"l":"E","t":"troubles statiques du genou","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(671, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'Concernant la gonarthrose fémoro-patellaire: (Cocher la ou les Réponses justes)', '[{"l":"A","t":"intéresse souvent le compartiment interne de l’articulation fémoro-patellaire","c":false},{"l":"B","t":"la douleur est réveillée à l’extension contrariée de la jambe","c":true},{"l":"C","t":"l’amyotrophie du quadriceps et épanchements intra-articulaire peuvent être présent","c":true},{"l":"D","t":"la douleur réveille le patient la nuit lors de changement de position","c":false},{"l":"E","t":"l’augmentation des contraintes sur la route s’exerce en cas du genu varum","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(672, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'Parmi les étiologies de la gonarthrose primitive', '[{"l":"A","t":"la surcharge pondérale","c":true},{"l":"B","t":"l’ostéochondrite disséquante du genou","c":false},{"l":"C","t":"le vice architectural primitif","c":false},{"l":"D","t":"la gonarthrose à destruction rapide","c":true},{"l":"E","t":"la chondromalacie rotulienne","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(673, 6, 'Rhumatologie', 'Arthrose', NULL, true, true, 'L’ordonnance type de kinésithérapie pour gonarthrose doit comporter: (la Réponse Fausse)', '[{"l":"A","t":"Renforcement musculaire","c":false},{"l":"B","t":"Gain d’amplitude articulaire","c":false},{"l":"C","t":"Travail proprioceptif","c":false},{"l":"D","t":"Autoprogramme","c":false},{"l":"E","t":"Ultrasons et massages","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(674, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'À propos de la gonarthrose: (là où les réponses justes)', '[{"l":"A","t":"il s’agit d’une synovite chronique du genou","c":false},{"l":"B","t":"le bilan inflammatoire est toujours positif","c":false},{"l":"C","t":"les signes radiologiques ne sont pas corrélés à la symptomatologie clinique","c":true},{"l":"D","t":"le traitement de première intention est la corticothérapie par voie générale","c":false},{"l":"E","t":"le genu varum est un facteur de risque d’apparition d’une gonarthrose fémoro-tibiale interne","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(675, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'Devant une gonarthrose fémoro-tibial le interne, vous prescrivez une ordonnance de kinésithérapie comportant tous les moyens suivants sauf:', '[{"l":"A","t":"renforcement musculaire analytique des muscles valgisants","c":false},{"l":"B","t":"renforcement des muscles stabilisateurs du genou (ischio-jambiers, quadriceps)","c":false},{"l":"C","t":"Gain amplitude articulaire, lutte contre le flessum, posture et auto posture","c":false},{"l":"D","t":"travaille proprioceptif","c":false},{"l":"E","t":"ultrasons, massages","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(676, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'Les facteurs de risque dans la gonarthrose primitives sont: (Qst Incomplète )', '[{"l":"A","t":"L’âge","c":true},{"l":"B","t":"Le sexe masculin,","c":false},{"l":"C","t":"La surcharge pondérale…","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(677, 6, 'Rhumatologie', 'Arthrose', NULL, false, true, 'Une Omarthrose', '[{"l":"A","t":"Est l’arthrose ????","c":false},{"l":"B","t":"Est l’arthrose de la gléno-humérale","c":true},{"l":"C","t":"Est une arthrose primitive fréquente","c":false},{"l":"D","t":"Elle entraîne une limitation des mouvements actifs et passifs","c":true},{"l":"E","t":"La radiographie de caractérise par un pincement de l’interligne articulaire et des ostéophytes","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(678, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'Parmi les causes de douleurs précoces tu les patients fracturés orientés en rééducation: (là où les réponses justes)', '[{"l":"A","t":"les phlébites","c":true},{"l":"B","t":"les déplacements secondaires des extrémités osseuses","c":true},{"l":"C","t":"l’arthrose","c":false},{"l":"D","t":"l’algodystrophie","c":true},{"l":"E","t":"la raideur articulaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(679, 31, 'Rhumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', NULL, false, true, 'Les complications les plus fréquentes à long terme sont:', '[{"l":"A","t":"La necrose dela tete femorale","c":true},{"l":"B","t":"La suppuration profonde","c":false},{"l":"C","t":"Une ankylose spontanee dela hanche","c":false},{"l":"D","t":"Une fracture du col du femur","c":false},{"l":"E","t":"Une coxarthrose","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(680, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Quelles sont les complications possibles des fractures per trochantériennes ? La/Les RJ', '[{"l":"A","t":"Osteonecrose dela tete femorale.","c":false},{"l":"B","t":"Pseudarthrose.","c":false},{"l":"C","t":"Coxarthrose post-traumatique.","c":true},{"l":"D","t":"Raideur dela hanche.","c":true},{"l":"E","t":"Complications de decubitus.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(681, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'La fracture uni-tubérositaire externe: La/Les RF', '[{"l":"A","t":"La fracture la plus frequente des plateaux tibiaux","c":false},{"l":"B","t":"S’accompagnetoujoursd’unenfoncement","c":true},{"l":"C","t":"Le traitement vise a retablir les surfaces articulaires","c":false},{"l":"D","t":"Pourvoyeuse d’arthrose du genou","c":false},{"l":"E","t":"C’est une fracture extra articulaire","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(682, 6, 'Rhumatologie', 'Arthrose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Les mesures proposées à un patient souffrant de gonarthrose: La/Les RJ', '[{"l":"A","t":"Repos total","c":false},{"l":"B","t":"Anti-inflammatoires nonsteroidien sau long cours","c":false},{"l":"C","t":"Infiltration d’acide hyaluronique","c":true},{"l":"D","t":"Cure thermale","c":true},{"l":"E","t":"Perte de poids si surpoids ou obesite","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(683, 11, 'Rhumatologie', 'Boiterie chez l’enfant', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Patiente âgée de 55 ans, consulta pour une douleur du genou survient après une station debout prolongée et qui cède au repos. Quels sont les éléments cliniques de diagnostic d’une gonarthrose ?', '[{"l":"A","t":"Une boiterie d’esquive la marcha","c":true},{"l":"B","t":"Une douleur de type mecanique","c":true},{"l":"C","t":"Presence des ignes inflammatoires locaux","c":false},{"l":"D","t":"Reveil avec un derouillage matinal>30min","c":false},{"l":"E","t":"Présence d’un craquement lors de changement de position","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(684, 6, 'Rhumatologie', 'Arthrose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le liquide articulaire dans la gonarthrose a les propriété(s) suivante(s):', '[{"l":"A","t":"Peut etre a l’origine d’un choc rotulien","c":true},{"l":"B","t":"Aseptique","c":true},{"l":"C","t":"Un nombre d’elements blancs<2000éléments/mm3","c":true},{"l":"D","t":"Riche en microcristaux","c":false},{"l":"E","t":"Trouble et fluide","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(685, 6, 'Rhumatologie', 'Arthrose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La gonarthrose est un rhumatisme:', '[{"l":"A","t":"Non inflammatoire chronique","c":true},{"l":"B","t":"Unilatéral,unicompartimental","c":false},{"l":"C","t":"Non evolutive","c":false},{"l":"D","t":"Touche surtout l’adulte et les uj etage","c":true},{"l":"E","t":"Les facteurs de risque:l’obesite et lese xe feminin","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(686, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La gonarthrose: La RJ', '[{"l":"A","t":"Est un rhumatisme inflammatoire chronique,","c":false},{"l":"B","t":"Est la resultante de phenomenes mecaniques seuls.","c":false},{"l":"C","t":"Elle évolue par des poussées congestives et des rémissions.","c":true},{"l":"D","t":"Elle est toujours primitive.","c":false},{"l":"E","t":"Elle est caractérisée par la présence de syndesmophytes ala radiographie.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(687, 6, 'Rhumatologie', 'Arthrose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La gonarthrose peut être secondaire: La/Les RJ', '[{"l":"A","t":"Fracture articulaire du genou","c":true},{"l":"B","t":"Chondromatose synoviale","c":true},{"l":"C","t":"Mono-arthrite inflammatoire","c":true},{"l":"D","t":"Synovite v ill o-nodulaire","c":false},{"l":"E","t":"Troubles statiques du genou","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(688, 31, 'Rhumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'L’interligne de la hanche est pincé au cours de:', '[{"l":"A","t":"1 - La coxarthrose primitive","c":true},{"l":"B","t":"2 - La nécrose de la tête fémorale","c":false},{"l":"C","t":"3 - La coxite rhumatoïde","c":true},{"l":"D","t":"4 - l’algodystrophie","c":false},{"l":"E","t":"Les 4 propositions sont justes","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(689, 6, 'Rhumatologie', 'Arthrose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Un homme âgé de 53 ans se plaint d’une douleur inguino-crurale antérieure évoluant depuis un mois. Cette topographie douloureuse est compatible avec:', '[{"l":"A","t":"Névralgie crurale","c":true},{"l":"B","t":"Névralgie sciatique","c":false},{"l":"C","t":"Sacro-iléite","c":false},{"l":"D","t":"Coxarthrose","c":true},{"l":"E","t":"Coxite","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(690, 2, 'Rhumatologie', 'Arthrose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Une douleur de hanche avec radiographie strictement normale et hyperfixation scintigraphique peut correspondre à:', '[{"l":"A","t":"Une ostéonécrose de la tête fémorale","c":true},{"l":"B","t":"Une algodystrophie de hanche","c":true},{"l":"C","t":"Une coxarthrose débutante sur dysplasie","c":false},{"l":"D","t":"Une maladie de Paget","c":false},{"l":"E","t":"Une coxite débutante au cours de la polyarthrite rhumatoïde","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(691, 6, 'Rhumatologie', 'Arthrose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Une arthrite du genou évoluant depuis 6 mois sans aucune lésion radiologique doit faire évoquer: (cochez la ou les réponses justes)', '[{"l":"A","t":"une tuberculose","c":true},{"l":"B","t":"b - une monoarthrite rhumatoïde","c":true},{"l":"C","t":"c - une poussée congestive d’arthrose","c":false},{"l":"D","t":"d - une arthropathie tabétique","c":false},{"l":"E","t":"e - aucune des propositions précédentes","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(692, 6, 'Rhumatologie', 'Arthrose', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le grade 2 de la classification de Kellgren-Lawrence de la gonarthrose correspond à:', '[{"l":"A","t":"Présence de géodes","c":false},{"l":"B","t":"Pincement de l’interligne articulaire","c":false},{"l":"C","t":"Déminéralisation sous chondrale","c":false},{"l":"D","t":"Présence d’ostéophytes avec respect de l’interligne articulaire","c":true},{"l":"E","t":"Sclérose sous chondrale","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(693, 6, 'Rhumatologie', 'Arthrose', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'La fracture uni-tubérositaire exteme est: (cochez les réponses justes)', '[{"l":"A","t":"La fracture la plus fréquente des plateaux tibiaux","c":false},{"l":"B","t":"S’accompagne toujours d’un enfoncement","c":false},{"l":"C","t":"Est une fracture extra articulaire","c":false},{"l":"D","t":"Le traitement vise à rétablir les surfaces articulaires","c":false},{"l":"E","t":"Pourvoyeuse d’arthrose du genou","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(694, 2, 'Rhumatologie', 'Polyarthrite rhumatoïde', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Quels sont les diagnostics différentiels d’une polyarthrite rhumatoide débutante', '[{"l":"A","t":"Goutte","c":false},{"l":"B","t":"Maladie lupique","c":false},{"l":"C","t":"Lombosciatique commune","c":false},{"l":"D","t":"Gonarthrose","c":false},{"l":"E","t":"Maladie de Lyma","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(695, 6, 'Rhumatologie', 'Arthrose', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Au cours d’une coxarthrose secondaire, on doit rechercher systématiquement:', '[{"l":"A","t":"Une dysplasie cotyloidienne","c":false},{"l":"B","t":"Une dysplasie femorale","c":false},{"l":"C","t":"Une inégalité de longueur des membres Intérieurs","c":false},{"l":"D","t":"Un syndrome inflammatoire biologique","c":false},{"l":"E","t":"Un syndrome dysimmunitaire","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(696, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, true, true, 'Les radiographies réalisées:', '[{"l":"A","t":"Sont suffisantes","c":false},{"l":"B","t":"Doivent être complétées par un faux profil de Léquesne","c":false},{"l":"C","t":"Doivent être complétées par une incidence en 3/4 alaire du côté blesse","c":true},{"l":"D","t":"Doivent être complétées par une incidence en 3/4 obturateur","c":true},{"l":"E","t":"Doivent être complétées par des tomographies","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(697, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Concernant la goutte, cochez la (les) réponse(s) exacte(s):', '[{"l":"A","t":"Elle est plus fréquente chez la femme que chez l’homme","c":false},{"l":"B","t":"Les Crises aiguës typiques sont plus fréquentes à l’index","c":false},{"l":"C","t":"Les radiographies sont normales lors de la première Crise","c":true},{"l":"D","t":"Les lithiases urinaires sont radio opaques.","c":false},{"l":"E","t":"L’inflammation goutteuse peut intéresser les bourses séreuses et les tendons","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(698, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Parmi les propositions suivantes concernant la goutte et son traitement, cochez la (les) réponse(s)exacte(e):', '[{"l":"A","t":"Le traitement de l’accès aigu repose sur l’administration d’allopurinol","c":false},{"l":"B","t":"L’initiation d’un traitement hypo-uricémiant doit être associée à la colchicine.","c":true},{"l":"C","t":"Le traitement hypo-uricémiant doit être instauré le premier jour de la crise aigue","c":false},{"l":"D","t":"L’objectif de traitement hypo-uricémiant est de maintenir l’uricémie à moins de 60 mg/l","c":true},{"l":"E","t":"Le régime antigoutteux est hypercalorique, hyperpurinique est recommandé à vie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(699, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Parmi les propositions suivantes concernant la goutte, cochez la (les) réponse(s) exacte(s)', '[{"l":"A","t":"Le tophus est une manifestation fréquente de la goutte aigue.","c":false},{"l":"B","t":"Une lithiase rénale radio-transparente.","c":true},{"l":"C","t":"Asymétrie des lésions radiologiques avec une interligne articulaire tardivement conservé,","c":true},{"l":"D","t":"Un régime alimentaire riche en purines est recommandé à vie.","c":false},{"l":"E","t":"La colchicine est le traitement de référence de la crise de goutte.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(700, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, true, true, 'Parmi les propositions suivantes, cochez les RJ concernant la goutte:', '[{"l":"A","t":"L’examen clinique révèle des tophus lors de la goutte aigue","c":false},{"l":"B","t":"Les microcristaux se forment à partir d’une concentration de 70 mg/l de l’acide urique","c":true},{"l":"C","t":"Les radiographies normales lors des premiers accès","c":true},{"l":"D","t":"Le régime antigoutteux est hypercalorique, hyperpurinique","c":false},{"l":"E","t":"Une hyperuricémie non constante durant l’accès goutteux","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(701, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, true, true, 'Propositions parmi les suivantes sont exactes à propos des médicaments de la goutte ?', '[{"l":"A","t":"Colchicine est un hypo uricémiant","c":false},{"l":"B","t":"L’allopurinol est le traitement de référence de la crise de goutte","c":false},{"l":"C","t":"Les uricosuriques sont indiqués en cas de lithiase rénale","c":false},{"l":"D","t":"La corticothérapie générale ne doit être utilisée qu’exceptionnellement","c":true},{"l":"E","t":"La colchicine doit être associée aux autres antigoutteux en début du traitement","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(702, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Quelles propositions parmi les suivantes sont exactes à propos de la goutte?', '[{"l":"A","t":"Les règles hygiéno-diététiques sont recommandées à vie","c":true},{"l":"B","t":"Le régime antigoutteux est hypercalorique, hyperpurinique","c":false},{"l":"C","t":"Le tophus est la lésion pathognomonique de la goutte aigue","c":false},{"l":"D","t":"La crise aigüe disparait spontanément au bout de 5 à 10 jours","c":true},{"l":"E","t":"Une lithiase rénale radio-opaque visible sur Radiographie de l’abdomen sans préparation","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(703, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Parmi les propositions suivantes, cocher des réponses justes concernant la goutte:', '[{"l":"A","t":"Les lithiases urinaires sont de radio-opaques","c":false},{"l":"B","t":"Les règles hygiéno-diététiques sont recommandées à vie","c":true},{"l":"C","t":"Le régime antigoutteux est riche en viande ???","c":false},{"l":"D","t":"Le tophus est une manifestation de goutte aiguë","c":false},{"l":"E","t":"La colchicine est le traitement de référence de la crise de goutte","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(704, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Toutes les propositions suivantes s’appliquent une crise de goutte aigue typique sauf une laquelle (citez la réponse fausse)', '[{"l":"A","t":"Est parfois précédé par la prise d’alcool","c":false},{"l":"B","t":"La douleur siège à la Base du gros orteil","c":false},{"l":"C","t":"Réponse spectaculaire a la colchicine à des doses suffisantes","c":false},{"l":"D","t":"Peut s’accompagner d’une uricémie normale","c":false},{"l":"E","t":"Le Liquide synovial est mécanique (< 2000 éléments/mm3)","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(705, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Parmi les propositions suivantes concernant la goutte aigue, lesquelles sont inexactes: RF(s)', '[{"l":"A","t":"Les tophus","c":true},{"l":"B","t":"Insuffisance rénale","c":true},{"l":"C","t":"Radiographies normales lors des premiers accès","c":false},{"l":"D","t":"Une hyper uricémie non constante durant l’accès","c":false},{"l":"E","t":"La lithiase rénale","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(706, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'En faveur d’une crise aigüe de goutte: (Cocher la ou les Réponse(s) juste(s))', '[{"l":"A","t":"Toujours localisé au gros orteil","c":true},{"l":"B","t":"Parfois précédée de coliques néphrétiques","c":false},{"l":"C","t":"Le début est brutal souvent nocturne avec une impotence fonctionnelle","c":true},{"l":"D","t":"Réagit rapidement et favorablement à l’allopurinol à doses suffisantes","c":false},{"l":"E","t":"Peut être déclenchée par la prise des diurétiques thiazidiques","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(707, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, true, true, 'Le traitement de fond de la goutte repose sur: Cocher la ou les Réponse(s) juste(s)', '[{"l":"A","t":"Une corticothérapie à faible dose","c":false},{"l":"B","t":"Des anti-inflammation non stéroïdiens","c":false},{"l":"C","t":"Des mesures hygiéno-diététiques","c":false},{"l":"D","t":"Les urico-inhibiteurs","c":false},{"l":"E","t":"Les urico-suriques","c":true},{"l":"A","t":"Antécédent de lithiase rénale.","c":false},{"l":"B","t":"Tophus sous-cutané siégeant au niveau du pavillon de l’oreille.","c":false},{"l":"C","t":"Présence d’un trouble statique des membres inférieurs.","c":false},{"l":"D","t":"Arthropathies destructrices des pieds","c":false},{"l":"E","t":"Présence de cristaux de Piophosphate de calcium à l’analyse du liquide synovial.","c":true},{"l":"A","t":"(2,3,5) B.(1,4,5) C.(3,4,5) D.(1,3,5) E.(1,2,4)","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(708, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Concernant la colchicine:', '[{"l":"A","t":"Elle a une action hyperuricémiante","c":false},{"l":"B","t":"Elle a une action anti-inflammatoire","c":true},{"l":"C","t":"peut être remplacée par les AINS","c":true},{"l":"D","t":"Inhibe la xanthine–oxydase","c":false},{"l":"E","t":"représente un test thérapeutique de la crise aiguë de goutte","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(709, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Concernant la goutte: (la ou les réponses fausses)', '[{"l":"A","t":"Elle appartient au groupe des rhumatismes dégénératif chronique","c":true},{"l":"B","t":"l’uricémie est constamment normale au cours d’un accès aigu","c":true},{"l":"C","t":"une insuffisance rénale chronique peu compliqué l’évolution des gouttes chronique","c":false},{"l":"D","t":"le traitement de la maladie goutteuse chronique fait appel aux anti-inflammatoires nonstéroïdien","c":true},{"l":"E","t":"l’acide urique est le produit final du catabolisme des bases pyrimidiques","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(710, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Parmi les propositions suivantes concernant la goutte, cochez la ou les réponses fausses:', '[{"l":"A","t":"L’acide urique est le terme ultime du catabolisme des protéines","c":false},{"l":"B","t":"Caractérisé par des dépôts de cristaux de pyrophosphate de calcium dans les articulations.","c":true},{"l":"C","t":"Une hyperuricémie peut être observée au cours du traitement par les diurétiques","c":false},{"l":"D","t":"Peut s’accompagner par une uricémie durant l’accès goutteux.","c":false},{"l":"E","t":"L’insuffisance rénale aiguë est une manifestation fréquente de la goutte aigue.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(711, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Parmi les réponses suivantes concernant le traitement de la goutte, quelles sont celles qui sont exactes:', '[{"l":"A","t":"L’allopurinol et le traitement de référence de la crise de goutte.","c":false},{"l":"B","t":"L’initiation d’un traitement hypouricémiant doit être associée à la colchicine","c":true},{"l":"C","t":"Le traitement hypouricémiant doit être instaure le premier jour de la crise aigue.","c":false},{"l":"D","t":"L’objectif des traitements hypouricémiant est de maintenir l’uricémie à moins de 60 mg/l.","c":true},{"l":"E","t":"Tous les uricosuriques induisent un risque de lithiase urique.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(712, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Dans le traitement de l’algodystrophie on prescrit: (Cocher la réponse juste)', '[{"l":"A","t":"Les corticoïdes","c":false},{"l":"B","t":"Les antibiotiques","c":false},{"l":"C","t":"Les antipaludéens de synthèse","c":false},{"l":"D","t":"La calcitonine","c":true},{"l":"E","t":"La colchicine","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(713, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Concernant la goutte: La/Les RJ', '[{"l":"A","t":"Elle est plus fréquente chez la femme que chez l’homme","c":false},{"l":"B","t":"Les Crises aiguës typiques sont plus fréquentes à l’index","c":false},{"l":"C","t":"Les radiographies sont normales lors de la premièreCrise","c":true},{"l":"D","t":"Les lithiases urinaires sont radio opaques.","c":false},{"l":"E","t":"L’inflammation goutteuse peut interesser les bourses sereuses et les tendons","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(714, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Parmi les propositions suivantes concernant la goutte et son traitement: La/Les RJ', '[{"l":"A","t":"Le traitement de l’accès aigu repose sur l’administrationd’allopurinol","c":false},{"l":"B","t":"L’initiation d’un traitement hypo-uricemiant doit etre associee ala colchicine.","c":true},{"l":"C","t":"Le traitement hypo-uricémiant doit être instauré le premier jour del acr ise aigue","c":false},{"l":"D","t":"L’objectif de traitement hypo-uricémiant est de maintenirl’uricémieàmoinsde60mg/l","c":true},{"l":"E","t":"Le régime antigoutteux est hypercalorique, hyperpurinique est recommande a vie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(715, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Concernant la goutte: La/Les RJ', '[{"l":"A","t":"Le tophus est une manifestation fréquente de la goutteaiguë","c":false},{"l":"B","t":"Une lithiase renale radio-trans par ent e.","c":true},{"l":"C","t":"Asymétrie des lésions radiologiques avec une interligne articulaire tardivement conserve,","c":true},{"l":"D","t":"Un régime alimentaire riche en purines est recommandéàvie.","c":false},{"l":"E","t":"La colchicine est le traitement de référence de la crisedegoutte.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(716, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Concernant la goutte: Les RJ', '[{"l":"A","t":"L’examen clinique révèle des tophus lors de la goutteaiguë","c":false},{"l":"B","t":"Les microcristaux se forment à partir d’une concentrationde70mg/ldel’acideurique","c":true},{"l":"C","t":"Les radiographies normales lors des premiers acces","c":true},{"l":"D","t":"Le régime antigoutteux est hypercalorique, hyperpurinique","c":false},{"l":"E","t":"Une hyperuricémie non constante durant l’accès goutteux","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(717, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'À Propos des médicaments de la goutte: Les RJ', '[{"l":"A","t":"La colchicine est un hypouricemiant","c":false},{"l":"B","t":"L’allopurinol est le traitement de référence de la crisedegoutte","c":false},{"l":"C","t":"Les uricosuriques sont indiqués en cas de lithiase rénale","c":false},{"l":"D","t":"La corticothérapie générale ne doit être utilisée qu’exceptionnellement","c":true},{"l":"E","t":"La colchicine doit être associée aux autres antigoutteux en debut du traitement","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(718, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'À propos de la goutte: Les RJ', '[{"l":"A","t":"Les règles hygiéno-diététiques sont recommandées àvie","c":true},{"l":"B","t":"Régime antigoutteux est hypercalorique hyperpurinique","c":false},{"l":"C","t":"Le tophus est la lésion pathognomonique de la goutteaiguë","c":false},{"l":"D","t":"La crise aiguë disparaît spontanément au bout de 5à10jours","c":true},{"l":"E","t":"Une lithiase rénale radio-opa que visible sur Radiographie de l’abdomen sans preparation","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(719, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Concernant la goutte: Les RJ', '[{"l":"A","t":"Les lithiases urinaires sont de radio-opaques","c":false},{"l":"B","t":"Les règles hygiéno-diététiques sont recommandées àvie","c":true},{"l":"C","t":"Lerégimeantigoutteuxestricheenviande..","c":false},{"l":"D","t":"Le tophus est une manifestation de goutte aigue","c":false},{"l":"E","t":"La colchicine est le traitement de référence de la crisedegoutte","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(720, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Concernant la goutte: La/Les RF', '[{"l":"A","t":"L’acide urique est le terme ultime du catabolisme desprotéines","c":false},{"l":"B","t":"Caractérisé par des dépôts de cristaux de pyrophosphate de calcium dans les articulations.","c":true},{"l":"C","t":"Une hyperuricemie peut etre observee au cours du traitement parle s diuretiques","c":false},{"l":"D","t":"Peut s’accompagner par une uricémie durant l’accèsgoutteux.","c":false},{"l":"E","t":"L’insuffisance rénale aiguë est une manifestation frequente dela goutte aigue","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(721, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Concernant le traitement de la goutte: Les RJ', '[{"l":"A","t":"L’allopurinol et le traitement de référence de la crisedegoutte.","c":false},{"l":"B","t":"L’initiation d’un traitement hypouricémiant doit être associee ala colchicine","c":true},{"l":"C","t":"Le traitement hypouricémiant doit être instaure le premier jour del acr ise aigue.","c":false},{"l":"D","t":"L’objectif des traitements hypouricémiant est de maintenirl’uricémieàmoinsde60mg/l.","c":true},{"l":"E","t":"Tous les uricosuriques induisent un risque de lithiase urique.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(722, 28, 'Rhumatologie', 'Rhumatismes métaboliques (goutte)', NULL, false, true, 'Toutes les propositions suivantes s’appliquent une crise de goutte aigue typique sauf une laquelle ?', '[{"l":"A","t":"Est parfois precede parla prise d’alcool","c":false},{"l":"B","t":"LadouleursiègeàlaBasedugrosorteil","c":false},{"l":"C","t":"Réponse spectaculaire a la colchicine à des doses suffisantes","c":false},{"l":"D","t":"Peut s’accompagner d’une uricemie normale","c":false},{"l":"E","t":"Le Liquide synovial est mécanique (< 2000 éléments/mm3)","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
