(772, 4, 'Rhumatologie', 'Situations d’handicap et concept de qualité de vie', NULL, false, true, 'La sclérodermie systémique est une affection auto-immune du tissu conjonctif: La/Les RJ', '[{"l":"A","t":"Le diagnostic est surtout clinique.","c":true},{"l":"B","t":"Pas de traitements pe cif i que.","c":true},{"l":"C","t":"Debute apres l’age de60ans.","c":false},{"l":"D","t":"Le pronostic est conditionne par l’atteinte pulmonaire","c":true},{"l":"E","t":"Anomalies capillaro-scopiques sont pathognomoniques","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(773, 2, 'Rhumatologie', 'Connectivites', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Dans la poly myosite: La/Les RJ', '[{"l":"A","t":"L’association avec un neoplasie est possible.","c":true},{"l":"B","t":"L’emg est specifique.","c":false},{"l":"C","t":"Le traitement repose sur la corticotherapie.","c":true},{"l":"D","t":"La biopsie montre une invasion lymphocytique de fibresnécrotiques.","c":false},{"l":"E","t":"Il existe une inflammation musculaire chronique dans un contexte auto-immun.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A","EMD OTR section B"]'::jsonb),
(774, 2, 'Rhumatologie', 'Connectivites', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Concernant le traitement symptomatique du syndrome de Sjörgen: Les RF', '[{"l":"A","t":"Une corticothérapie à faible dose améliore considérablementlesyndromesecoculo-buccal","c":true},{"l":"B","t":"Les anti-inflammatoires nonsteroidien s representent le traitement de1ere intention des atteintes articulaires","c":false},{"l":"C","t":"Les larmes artificielles peuvent améliorer la secheresse oculaire","c":false},{"l":"D","t":"La bromhexine améliore parfaitement la sécheressebuccale","c":true},{"l":"E","t":"Leméthotrexatepeutêtreutilisédansletraitement des atteintes articulaires","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
