(782, 10, 'Rhumatologie', 'Ostéopathies', NULL, true, true, 'Quel est parmi ses profils, celui qui est compatible avec une ostéomalacie carentielle:', '[{"l":"A","t":"Calcémie, phosphorémie, calciurie des 24 heures et phosphatases alcalines normales","c":false},{"l":"B","t":"Calcémie élevée, phosphorémie basse, et phosphatases alcaline élevée et hypercalciurie","c":false},{"l":"C","t":"Calcémie normales ou élevée, hypercalciurie, PTH basse, phosphatases alcalines élevée","c":false},{"l":"D","t":"Hypocalcémie, hypophosphorémie, hypocalciurie, phosphatases alcalines élevée","c":true},{"l":"E","t":"Hypocalcémie, hyperphosphorémie, PTH élevée","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
